-- Read-only, IDs/counts only. Live execution requires owner approval under POLICY.md.
WITH m(id) AS (VALUES ('f8f89ee1-66e7-4e42-a848-ca3d6e4f5c51'),('12dca885-1548-43d2-b219-46d04095c26e'),('24651e6b-7cf9-43b5-8b90-6a521679c6a7'),('bcd03d50-9604-43a7-be0b-5f1ec5594794')) SELECT (SELECT count(*) FROM public.members WHERE tenant IS DISTINCT FROM 'guest') AS non_guest_members, (SELECT count(*) FROM public.members JOIN m USING(id)) AS listed_members, (SELECT count(*) FROM public.conversations) AS conversations, (SELECT count(*) FROM public.conversations c JOIN m ON m.id=c.member_id) AS related_conversations, (SELECT count(*) FROM public.preferences p JOIN m ON m.id=p.member_id) AS related_preferences, (SELECT count(*) FROM public.corrections c JOIN m ON m.id=c.member_id) AS related_corrections, (SELECT count(*) FROM public.sessions s JOIN m ON m.id=s.member_id) AS related_sessions, (SELECT count(*) FROM public.guest_usage g JOIN m ON m.id=g.member_id) AS related_guest_usage;
